import numpy as np
import jax.numpy as jnp
from jax import grad

D=np.load('data/logistic.npz')
x=jnp.array(D['x']); y=jnp.array(D['y']); w=jnp.array(D['w'])

# candidate 1: mean logistic loss log(1+exp(-y*(x@w)))

def loss_mean(w):
    logits = jnp.dot(x, w)
    return jnp.mean(jnp.logaddexp(0.0, -y*logits))

# candidate 2: sum

def loss_sum(w):
    logits = jnp.dot(x, w)
    return jnp.sum(jnp.logaddexp(0.0, -y*logits))

# candidate 3: with sigmoid and y in {0,1}
# but y is -1/1 so maybe logistic loss like log(1+exp(-y*...))


ref=np.load('reference/grad_logistic.npy')

for name, f in [('mean', loss_mean), ('sum', loss_sum)]:
